-- Content migration: retain existing IDs, images, fees, and publication state.
-- Supplied schemes use annual hours and credits; marks were not supplied.
UPDATE "Program" SET "duration" = '3 Years', "updatedAt" = CURRENT_TIMESTAMP
WHERE "listingPage" = 'DAE';

UPDATE "Program" SET "department" = 'CSIT', "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" IN ('dae-software', 'dae-cit') OR ("listingPage" = 'DAE' AND "department" IN ('cit', 'software', 'CIT', 'Software Technology', 'Computer Information Technology'));

